"""Native component hints without external framework packs or page templates."""
import re
COMPONENTS = {'navigation': {'signals': ('nav', 'menu', 'navbar', 'navigation'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'hero': {'signals': ('hero', 'banner', 'masthead', 'carousel', 'slider'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'cards': {'signals': ('card', 'teaser', 'tile', 'news', 'product', 'article'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'forms': {'signals': ('form', 'input', 'select', 'textarea', 'search'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'tables': {'signals': ('table', 'thead', 'tbody'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'lists': {'signals': ('listing', 'list', 'pagination', 'results'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'disclosure': {'signals': ('accordion', 'collapse', 'details', 'modal', 'dialog'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'media': {'signals': ('img', 'picture', 'video', 'audio', 'figure'), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}, 'footer': {'signals': ('footer',), 'guidance': 'Use native semantics, accessible names, visible focus and responsive styling. Preserve declared action and control contracts.'}}

def retrieve_framework_knowledge(inventory,framework='source'):
    COMPONENTS.setdefault('document',{'signals':(), 'guidance':'Use a titled document, language, native landmarks and coherent heading hierarchy; preserve source facts and declared actions.'})
    signals=set(re.findall(r'[a-z]+',' '.join(inventory.get('signals',[])).lower()))
    selected=[name for name,row in COMPONENTS.items()if signals & set(row['signals'])]
    if 'document' not in selected:selected.insert(0,'document')
    return [{'component':name,'guidance':COMPONENTS[name]['guidance'],'source':'https://www.w3.org/WAI/tutorials/','knowledge_version':'native-component-guidance-v1','examples':[]}for name in selected]
